//! Compares `tests/data/regexp/corpus.txt` (generated by qjs, see
//! `tests/data/regexp/gen-corpus.js`) with the engine.

extern crate std;

use super::*;
use std::format;
use std::string::{String, ToString};
use std::vec::Vec;

const CORPUS: &str = include_str!("../../../../tests/data/regexp/corpus.txt");

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Num(f64),
    /// UTF-16 code units (JSON strings may hold lone surrogates).
    Str(Vec<u16>),
    Arr(Vec<Json>),
}

struct JsonParser<'a> {
    s: &'a [u8],
    i: usize,
}

impl JsonParser<'_> {
    fn value(&mut self) -> Json {
        match self.s[self.i] {
            b'n' => {
                self.i += 4;
                Json::Null
            }
            b'"' => Json::Str(self.string()),
            b'[' => {
                self.i += 1;
                let mut v = Vec::new();
                if self.s[self.i] == b']' {
                    self.i += 1;
                    return Json::Arr(v);
                }
                loop {
                    v.push(self.value());
                    let c = self.s[self.i];
                    self.i += 1;
                    if c == b']' {
                        return Json::Arr(v);
                    }
                    assert_eq!(c, b',');
                }
            }
            _ => {
                let start = self.i;
                while self.i < self.s.len() && matches!(self.s[self.i], b'-' | b'0'..=b'9' | b'.') {
                    self.i += 1;
                }
                let t = core::str::from_utf8(&self.s[start..self.i]).unwrap();
                Json::Num(t.parse().unwrap())
            }
        }
    }

    fn string(&mut self) -> Vec<u16> {
        self.i += 1;
        let mut out = Vec::new();
        loop {
            let c = self.s[self.i];
            match c {
                b'"' => {
                    self.i += 1;
                    return out;
                }
                b'\\' => {
                    let e = self.s[self.i + 1];
                    self.i += 2;
                    match e {
                        b'u' => {
                            let h = core::str::from_utf8(&self.s[self.i..self.i + 4]).unwrap();
                            out.push(u16::from_str_radix(h, 16).unwrap());
                            self.i += 4;
                        }
                        b'n' => out.push(10),
                        b't' => out.push(9),
                        b'r' => out.push(13),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        other => out.push(other as u16),
                    }
                }
                _ => {
                    // A UTF-8 sequence.
                    let len = match c {
                        0x00..=0x7F => 1,
                        0xC0..=0xDF => 2,
                        0xE0..=0xEF => 3,
                        _ => 4,
                    };
                    let ch = core::str::from_utf8(&self.s[self.i..self.i + len])
                        .unwrap()
                        .chars()
                        .next()
                        .unwrap();
                    let mut buf = [0u16; 2];
                    out.extend_from_slice(ch.encode_utf16(&mut buf));
                    self.i += len;
                }
            }
        }
    }
}

fn parse_json(line: &str) -> Json {
    JsonParser {
        s: line.as_bytes(),
        i: 0,
    }
    .value()
}

fn result_json(r: &ExecResult) -> Json {
    match r {
        ExecResult::Match(c) => Json::Arr(
            (0..c.len())
                .map(|i| match c.get(i) {
                    Some((s, e)) => {
                        Json::Arr(alloc::vec![Json::Num(s as f64), Json::Num(e as f64)])
                    }
                    None => Json::Null,
                })
                .collect(),
        ),
        ExecResult::NoMatch => Json::Null,
        ExecResult::OutOfFuel(_) => Json::Str("out of fuel".encode_utf16().collect()),
        ExecResult::StackOverflow => Json::Str("stack overflow".encode_utf16().collect()),
    }
}

/// Checks every case; returns the number of cases. Panics with the first differences.
pub(super) fn check_corpus(corpus: &str) -> usize {
    let mut failures = Vec::new();
    let mut n = 0;
    for line in corpus.lines() {
        let Json::Arr(v) = parse_json(line) else {
            panic!("bad line {line}")
        };
        let (Json::Str(pattern), Json::Str(flags)) = (&v[0], &v[1]) else {
            panic!("bad line {line}")
        };
        n += 1;
        let flags = Flags::parse(flags).unwrap();
        let compiled = compile(pattern, flags);
        if v.len() == 3 {
            let Json::Str(expect) = &v[2] else { panic!() };
            let expect = String::from_utf16(expect).unwrap();
            let got = match &compiled {
                Ok(_) => "compiled".to_string(),
                Err(e) => format!("!SyntaxError: {}", e.message()),
            };
            if got != expect {
                failures.push(format!("{line}\n    got: {got}"));
            }
            continue;
        }
        let prog = match compiled {
            Ok(p) => p,
            Err(e) => {
                failures.push(format!("{line}\n    got: !SyntaxError: {}", e.message()));
                continue;
            }
        };
        let (Json::Str(input), Json::Num(last_index)) = (&v[2], &v[3]) else {
            panic!("bad line {line}")
        };
        let start = if flags.contains(Flags::GLOBAL) || flags.contains(Flags::STICKY) {
            *last_index as usize
        } else {
            0
        };
        let mut fuel = 500_000_000;
        let r = exec(
            &prog,
            Input::Utf16(input),
            start,
            &mut fuel,
            ExecLimits::default(),
        );
        let got = result_json(&r);
        if got != v[4] {
            failures.push(format!("{line}\n    got: {got:?}"));
            continue;
        }
        if input.iter().all(|&u| u < 256) {
            let latin1: Vec<u8> = input.iter().map(|&u| u as u8).collect();
            let mut fuel = 500_000_000;
            let r = exec(
                &prog,
                Input::Latin1(&latin1),
                start,
                &mut fuel,
                ExecLimits::default(),
            );
            if result_json(&r) != v[4] {
                failures.push(format!("{line}\n    latin1 differs: {:?}", result_json(&r)));
            }
        }
    }
    if !failures.is_empty() {
        let shown: Vec<&str> = failures.iter().take(40).map(|s| s.as_str()).collect();
        panic!(
            "{} of {n} corpus cases differ from qjs:\n{}",
            failures.len(),
            shown.join("\n")
        );
    }
    n
}

/// Every 7th exec case of the corpus again, suspended every 3 steps.
#[test]
fn qjs_corpus_resumed() {
    let mut n = 0;
    for (k, line) in CORPUS.lines().enumerate().filter(|(k, _)| k % 7 == 0) {
        let Json::Arr(v) = parse_json(line) else {
            panic!()
        };
        if v.len() == 3 {
            continue;
        }
        let (Json::Str(pattern), Json::Str(flags), Json::Str(input), Json::Num(li)) =
            (&v[0], &v[1], &v[2], &v[3])
        else {
            panic!()
        };
        let flags = Flags::parse(flags).unwrap();
        let prog = compile(pattern, flags).unwrap();
        let start = if flags.contains(Flags::GLOBAL) || flags.contains(Flags::STICKY) {
            *li as usize
        } else {
            0
        };
        let mut fuel = 3;
        let mut r = exec(
            &prog,
            Input::Utf16(input),
            start,
            &mut fuel,
            ExecLimits::default(),
        );
        let mut steps = 0u64;
        while let ExecResult::OutOfFuel(state) = r {
            steps += 3;
            assert!(steps < 500_000_000, "line {k}");
            let state = ExecState::from_words(&state.to_words()).unwrap();
            fuel = 3;
            r = resume(
                &prog,
                Input::Utf16(input),
                state,
                &mut fuel,
                ExecLimits::default(),
            );
        }
        assert_eq!(result_json(&r), v[4], "{line}");
        n += 1;
    }
    assert!(n > 1000, "{n}");
}

#[test]
fn qjs_corpus() {
    let n = check_corpus(CORPUS);
    assert!(n > 10_000, "{n}");
}

/// A larger corpus made out of tree (`qjs gen-corpus.js SEED SCALE`), named by
/// `DJS_REGEXP_CORPUS`.
#[test]
#[ignore]
fn qjs_corpus_external() {
    let path = std::env::var("DJS_REGEXP_CORPUS").expect("set DJS_REGEXP_CORPUS");
    let text = std::fs::read_to_string(path).unwrap();
    std::println!("{} cases match", check_corpus(&text));
}
